package com.bank.comp;

import java.util.*;
import java.util.logging.*;

public class CompensationDemo {
    private static final Logger log = Logger.getLogger("Compensation");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Rajesh", 1200000), new Employee("Priya", 900000),
            new Employee("Vikram", 2500000), new Employee("Sneha", 1500000));
        CompensationService service = new CompensationService();

        service.topEarner(employees)
            .ifPresent(e -> log.info(() -> "Top earner (reduce maxBy): " + e.getName()));
        service.topEarnerShort(employees)
            .ifPresent(e -> log.info(() -> "Top earner (Stream.max): " + e.getName()));
        log.info(() -> "Empty roster top earner present? "
            + service.topEarner(List.of()).isPresent());
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final double salary;
    Employee(String name, double salary) { this.name = name; this.salary = salary; }
    String getName() { return name; }
    double getSalary() { return salary; }
}

// ─── Would be in service/CompensationService.java ───
class CompensationService {
    private final Comparator<Employee> bySalary =
        Comparator.comparingDouble(Employee::getSalary);

    // reduce with BinaryOperator.maxBy — shows the underlying mechanism
    Optional<Employee> topEarner(List<Employee> employees) {
        return employees.stream().reduce(java.util.function.BinaryOperator.maxBy(bySalary));
    }

    // Stream.max — the direct, clearest shorthand for the same result
    Optional<Employee> topEarnerShort(List<Employee> employees) {
        return employees.stream().max(bySalary);
    }
}
